function fewestCopies(a: string, b: string): number {
  const m = b.length;
  const fail = new Array(m).fill(0); // fail[i] = longest proper border of b[0..i]
  for (let i = 1, k = 0; i < m; i++) {
    while (k > 0 && b[i] !== b[k]) k = fail[k - 1];
    if (b[i] === b[k]) k++;
    fail[i] = k;
  }
  const copies = Math.ceil(m / a.length) + 1;
  const total = copies * a.length;
  for (let i = 0, k = 0; i < total; i++) {
    const c = a[i % a.length]; // read the repeated text without building it
    while (k > 0 && c !== b[k]) k = fail[k - 1];
    if (c === b[k]) k++;
    if (k === m) return Math.ceil((i + 1) / a.length);
  }
  return -1;
}

