class Solution:
    def fewestCopies(self, a: str, b: str) -> int:
        m, n = len(b), len(a)
        fail = [0] * m  # fail[i] = longest proper border of b[:i + 1]
        k = 0
        for i in range(1, m):
            while k and b[i] != b[k]:
                k = fail[k - 1]
            if b[i] == b[k]:
                k += 1
            fail[i] = k
        copies = -(-m // n) + 1
        k = 0
        for i in range(copies * n):
            c = a[i % n]  # read the repeated text without building it
            while k and c != b[k]:
                k = fail[k - 1]
            if c == b[k]:
                k += 1
            if k == m:
                return -(-(i + 1) // n)
        return -1

